/** MIME type for a project video, from its extension. */
export function videoType(src: string): string {
    return src.split('.').pop()?.toLowerCase() === 'webm' ? 'video/webm' : 'video/mp4';
}

/** Poster next to the video: demo.mp4 -> demo.poster.webp (generated by `npm run media:posters`). */
export function videoPoster(src: string): string {
    return src.replace(/\.[^./]+$/, '.poster.webp');
}

export function prefersReducedMotion(): boolean {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

let observer: IntersectionObserver | undefined;

/**
 * Play the videos under `root` only while they are on (or near) screen, and pause them otherwise.
 * Videos are rendered with preload="none", so nothing downloads until a video first comes into view.
 * With reduced motion, videos never autoplay and keep showing their poster.
 */
export function playVideosWhenVisible(root: ParentNode): void {
    observer?.disconnect();
    if (prefersReducedMotion()) return;

    observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                const video = entry.target as HTMLVideoElement;
                if (entry.isIntersecting) {
                    video.play().catch(() => {}); // autoplay can be refused (e.g. data saver); the poster stays
                } else {
                    video.pause();
                }
            }
        },
        { rootMargin: '200px 0px' }
    );
    root.querySelectorAll('video').forEach((video) => observer?.observe(video));
}
